#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("USAGE\n");
        return 1;
    }
    char *pattern = argv[1];
    char *string = argv[2];
    int pattern_len = strlen(pattern);
    int string_len = strlen(string);
    int match = 0;
    for (int i = 0; i < string_len; i++) {
        if (pattern[0] == '*' && pattern_len == 1) {
            match = 1;
            break;
        }
        if (pattern[0] == string[i]) {
            match = 1;
            for (int j = 1; j < pattern_len; j++) {
                if (pattern[j] != '*' && pattern[j] != string[i + j - 1]) {
                    match = 0;
                    break;
                }
            }
            if (match) break;
        }
    }
    if (match) printf("MATCH\n");
    else printf("NO_MATCH\n");
    return 0;
}
